import {coachFor,coachProfiles,plainLanguage,movementGlossary} from './coach-data.js';
import {AnatomyViewer} from './viewer.js';
import {lessons,lessonFor,nameFor} from './anatomy-data.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const regions={all:'Corps entier',head:'Tête et cou',trunk:'Tronc',upper:'Bras',hands:'Mains',lower:'Jambes',feet:'Pieds'};
const category=s=>({bone:'Os',muscle:'Muscle',tendon:'Structure tendineuse',cartilage:'Cartilage',tooth:'Dent'})[s.category]||'Structure';
const side=s=>s==='left'?'Gauche':s==='right'?'Droit':'Médian';
let stats={xp:0,explored:[],correct:0,bestCombo:0,sessions:[],days:[]};try{Object.assign(stats,JSON.parse(localStorage.getItem('myo-quest-v1')||'{}'));}catch{}
let atlas,structures=[],viewer,selected=null,mode='explore',quiz=null,quizRegion='essentials',quizType='name',ready=false;
const lesson=s=>lessonFor(s?.key||'');
const label=s=>s?.labelFr||nameFor(s);
function save(){try{localStorage.setItem('myo-quest-v1',JSON.stringify(stats));}catch{}updateStats();}
function updateStats(){$('#header-xp').textContent=`${stats.xp} XP`;$('#level-label').textContent=`Niveau ${1+Math.floor(stats.xp/150)}`;}
function award(n){stats.xp+=n;const d=new Date().toLocaleDateString('en-CA');if(!stats.days.includes(d))stats.days.push(d);save();}
function welcome(){$('#detail').innerHTML=`<div class="welcome"><div class="eyebrow">Révisions coach sportif</div><h1>Comprendre le muscle.<br>Expliquer le mouvement.</h1><p>Sélectionnez un muscle pour relier sa fonction, ses attaches et son rôle en salle.</p><button class="primary wide" id="study-biceps">Étudier le biceps</button><button class="quiet wide" id="welcome-quiz">M’entraîner avec un défi →</button><div class="welcome-list"><strong>Les trois questions à retenir</strong>Quel mouvement produit-il ?<br>Quels os relie-t-il ?<br>Comment intervient-il dans un exercice ?</div></div>`;$('#welcome-quiz').onclick=()=>setMode('quiz');$('#study-biceps').onclick=()=>{const s=structures.find(s=>s.key==='biceps_brachii_long'&&s.side==='left');if(s)pick(s.id,true);};$('#study-biceps').disabled=!ready;}
function updateRestore(){$('#restore').hidden=!viewer?.isolated&&!viewer?.hidden.size&&!viewer?.regionIds&&!viewer?.revealed;}
function pick(id,focus=false){if(!ready)return;selected=structures.find(s=>s.id===id);if(!selected)return;viewer.select(id);updateRestore();if(focus){if(selected.category==='muscle'&&selected.layer==='deep')viewer.reveal(id);else viewer.focus(id);if(viewer.regionIds)$('#region').value=selected.region;updateRestore();}if(mode==='quiz'&&quiz&&!quiz.answered){quiz.selection=id;renderQuiz();return;}if(mode==='quiz')return;if(!stats.explored.includes(id)){stats.explored.push(id);award(5);}renderDetail();}
function renderDetail(){const s=selected;if(!s)return welcome();const l=lesson(s),c=coachFor(l);const related=structures.filter(x=>x.key===s.key&&x.category===s.category);$('#detail').innerHTML=`<div class="eyebrow">${category(s)} · ${esc(regions[s.region]||'Corps')}</div><h2>${esc(l?.name||label(s))}</h2>${l&&label(s).includes('·')?`<p class="part-caption">Sélection 3D : ${esc(label(s).split('·').slice(1).join('·').trim())}. Fiche du muscle complet.</p>`:''}<div class="study-tools"><div class="side-select">${related.length>1?related.map(x=>`<button data-side="${esc(x.id)}" class="${x.id===s.id?'active':''}">${side(x.side)}</button>`).join(''):`<span class="part">${side(s.side)}</span>`}</div><div class="detail-actions"><button id="focus">Cadrer</button><button id="isolate" class="${viewer.isolated?'active':''}">${viewer.isolated?'Tout voir':'Isoler'}</button><button id="hide">Masquer</button></div></div>${l?`<section class="study-function"><h3>À quoi sert ce muscle ?</h3><p>${esc(c.plain)}</p></section><section class="attachments"><h3>D’où part-il ? Où s’attache-t-il ?</h3><dl><div><dt><span>01</span> Origine <small>point de départ anatomique</small></dt><dd>${esc(c.originSimple||l.origin)}</dd></div><div><dt><span>02</span> Insertion <small>point d’arrivée anatomique</small></dt><dd>${esc(c.insertionSimple||l.insertion)}</dd></div></dl><p class="attachment-note">Les deux attaches peuvent se rapprocher : l’os qui bouge dépend de l’appui et de l’exercice.</p></section><section class="coach-context"><div class="eyebrow">Le lien avec la salle</div>${c.exercise?`<h3>${esc(c.exercise)}</h3>`:''}<p>${esc(c.gym)}</p>${c.exercise?'<small>Exemple de participation au mouvement, avec d’autres muscles.</small>':''}</section>${c.remember?`<p class="exam-note"><strong>À retenir pour l’examen</strong>${esc(c.remember)}</p>`:''}<details class="anatomy-details"><summary>Aller plus loin en anatomie</summary><p class="latin">${esc(l.latin)}</p><strong>Fonctions anatomiques</strong><p>${esc(l.action)}</p><strong>Origine précise</strong><p>${esc(l.origin)}</p><strong>Insertion précise</strong><p>${esc(l.insertion)}</p><strong>Innervation</strong><p>${esc(l.nerve)}</p><p>${esc(l.note)}</p><a class="source-link" href="${esc(l.source)}" target="_blank" rel="noopener">Référence anatomique ↗</a></details><details class="movement-glossary"><summary>Décoder les mots du mouvement</summary>${movementGlossary.map(([term,definition])=>`<strong>${esc(term)}</strong><p>${esc(definition)}</p>`).join('')}</details>`:`<p class="function-text">${s.category!=='muscle'?'Un repère pour comprendre où les muscles s’attachent.':'Cette structure peut être explorée en 3D ; sa fiche d’étude reste à documenter.'}</p><p class="note">${s.category!=='muscle'?'Sélectionnez un muscle voisin pour découvrir son mouvement et ses attaches.':'Elle est exclue des défis tant que sa fiche n’est pas documentée.'}</p>`}`;
$('#detail').scrollTop=0;$('#detail').querySelectorAll('[data-side]').forEach(b=>b.onclick=()=>pick(b.dataset.side,true));$('#focus').onclick=()=>viewer.focus(s.id);$('#isolate').onclick=()=>{viewer.isolate();updateRestore();renderDetail();};$('#hide').onclick=()=>{viewer.hideSelected();updateRestore();};}
function setMode(next){mode=next;$('#detail').classList.toggle('quiz-panel',next==='quiz');$('#workspace').hidden=false;$('#progress-page').hidden=true;document.body.classList.toggle('quiz-on',next==='quiz');document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===next);b.setAttribute('aria-pressed',String(b.dataset.mode===next));});$('#search').closest('.search-wrap').hidden=next==='quiz';$('#search-results').hidden=true;$('#layers').disabled=false;$('#hover-label').hidden=true;if(next==='quiz'){if(quiz?.answered&&quiz.correctId)viewer?.reveal(quiz.correctId);else viewer?.select(quiz?.selection||null);renderQuiz();}else{viewer?.select(selected?.id||null);renderDetail();}requestAnimationFrame(()=>viewer?.resize());}
function normalize(s){return s.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();}
function search(){const q=normalize($('#search').value.trim());const target=$('#search-results');if(!q){target.hidden=true;return;}const seen=new Set();const hits=structures.filter(s=>{const key=s.key;if(seen.has(key)||!normalize(label(s)+' '+s.sourceName).includes(q))return false;seen.add(key);return true;}).slice(0,30);target.hidden=false;target.innerHTML=hits.length?hits.map(s=>`<button data-pick="${esc(s.id)}"><span>${esc(label(s))}</span><small>${category(s)}</small></button>`).join(''):'<div class="search-empty">Aucune structure trouvée. Essayez un autre nom.</div>';target.querySelectorAll('button').forEach(b=>b.onclick=()=>{$('#search').value='';target.hidden=true;viewer.restore();$('#region').value='all';viewer.setLayer('all');$('#layers').value='all';pick(b.dataset.pick,true);});}
function pool(region){const list=structures.filter(s=>s.category==='muscle'&&lesson(s)&&(region==='essentials'?!!coachProfiles[lesson(s).id]:(region==='all'||s.region===region||(region==='upper'&&s.region==='hands')||(region==='lower'&&s.region==='feet'))));return [...new Map(list.map(s=>[lesson(s).id,lesson(s)])).values()];}
function startQuiz(){const list=pool(quizRegion);if(!list.length)return;for(let i=list.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[list[i],list[j]]=[list[j],list[i]];}quiz={type:quizType,questions:list.slice(0,5),index:0,correct:0,xp:0,combo:0,selection:null,answered:false,hint:false,finished:false};viewer.reset();viewer.select(null);$('#layers').value='all';$('#layers').disabled=false;viewer.frame(quizRegion==='essentials'?'all':quizRegion);$('#region').value=quizRegion==='essentials'?'all':quizRegion;$('#orientation').value='front';updateRestore();renderQuiz();}
function renderQuiz(){const el=$('#detail');el.classList.add('quiz-panel');if(!quiz){el.innerHTML=`<div class="eyebrow">Entraînement coach sportif</div><h2>Deux façons<br>de mémoriser.</h2><div class="quiz-types" role="group" aria-label="Type de défi"><button data-quiz-type="name" class="${quizType==='name'?'active':''}" aria-pressed="${quizType==='name'}"><strong>Trouve ce muscle</strong><span>Son nom → cliquez sur le corps.</span></button><button data-quiz-type="function" class="${quizType==='function'?'active':''}" aria-pressed="${quizType==='function'}"><strong>Quel muscle fait ça ?</strong><span>Sa fonction → identifiez-le sur le corps.</span></button></div><label for="quiz-region">Les muscles à réviser</label><select id="quiz-region">${Object.entries({essentials:'Essentiels coach',...regions}).map(([id,n])=>`<option value="${id}" ${id===quizRegion?'selected':''}>${n} · ${pool(id).length} muscles</option>`).join('')}</select><button class="primary wide" id="start-quiz" ${ready&&pool(quizRegion).length?'':'disabled'}>Commencer · 5 questions</button><p class="quiz-help">Sans chronomètre. Côté gauche ou droit accepté.<br>20 XP par bonne réponse · 10 XP avec un indice.</p>`;el.querySelectorAll('[data-quiz-type]').forEach(b=>b.onclick=()=>{quizType=b.dataset.quizType;renderQuiz();});$('#quiz-region').onchange=e=>{quizRegion=e.target.value;renderQuiz();};$('#start-quiz').onclick=startQuiz;return;}
if(quiz.finished){el.innerHTML=`<div class="eyebrow">Série terminée</div><h2>${quiz.correct===quiz.questions.length?'Bien joué !':'Chaque essai compte.'}</h2><div class="quiz-result-number">${quiz.correct}<span style="font-size:25px;color:var(--muted)"> / ${quiz.questions.length}</span></div><p>${quiz.xp} XP gagnés · Niveau ${1+Math.floor(stats.xp/150)}</p><button class="primary wide" id="again">Nouvelle série</button><button class="quiet wide" id="back-explore">Revenir à l’exploration</button>`;$('#again').onclick=()=>{quiz=null;renderQuiz();};$('#back-explore').onclick=()=>{quiz=null;setMode('explore');};return;}
const q=quiz.questions[quiz.index],s=structures.find(s=>s.id===quiz.selection),c=coachFor(q);el.innerHTML=`<div class="quiz-top"><span>Question ${quiz.index+1} / ${quiz.questions.length}</span><button class="quiet" id="end-quiz">Quitter</button></div><div class="quiz-progress"><i style="width:${(quiz.index+(quiz.answered?1:0))/quiz.questions.length*100}%"></i></div><div class="challenge-label">${quiz.type==='name'?'Trouvez sur le corps':'Quel muscle produit ce mouvement ?'}</div><p class="question">${esc(quiz.type==='name'?q.name:c.plain)}</p>${quiz.type==='function'&&!quiz.answered?`<p class="question-landmark"><strong>Repère pour le distinguer</strong>${esc(c.originSimple||q.origin)}</p>`:''}${quiz.answered?`<div class="feedback ${quiz.wasCorrect?'':'wrong'}" role="status"><strong>${quiz.wasCorrect?'Bonne réponse !':quiz.skipped?'La réponse à retenir':'Pas cette fois.'}</strong>${esc(q.name)}<p>${esc(c.plain)}</p>${c.exercise?`<p class="feedback-coach"><b>En salle · ${esc(c.exercise)}</b><br>${esc(c.gym)}</p>`:''}</div><button class="primary wide" id="next">${quiz.index===quiz.questions.length-1?'Voir mon résultat':'Question suivante'}</button>`:`<div class="selection ${s?'selected':''}" role="status">${s?(s.category==='muscle'?'Muscle sélectionné. Validez votre réponse.':'Cette structure n’est pas un muscle. Poursuivez votre recherche.'):'Cliquez sur un muscle dans le modèle.'}</div>${s?'<button class="quiet" id="quiz-hide">Masquer cette structure</button>':''}<button class="primary wide" id="validate" ${s?.category==='muscle'?'':'disabled'}>Valider ma réponse</button>${quiz.hint?`<p class="quiz-hint">${quiz.type==='name'?`Sa fonction : ${esc(c.plain)}`:`Autre repère : ${esc(plainLanguage(q.question))}`}</p>`:`<button class="quiet" id="hint">Obtenir un indice</button>`}<button class="quiet" id="skip" style="float:right">Passer</button><p class="quiz-help">Tournez le corps ou changez la région pour explorer.</p>`}`;
$('#end-quiz').onclick=()=>{quiz=null;viewer.select(null);$('#layers').disabled=false;renderQuiz();};if(quiz.answered)$('#next').onclick=nextQuestion;else{if($('#quiz-hide'))$('#quiz-hide').onclick=()=>{viewer.hideSelected();quiz.selection=null;updateRestore();renderQuiz();};$('#validate').onclick=()=>answer(false);$('#skip').onclick=()=>answer(true);if($('#hint'))$('#hint').onclick=()=>{quiz.hint=true;renderQuiz();};}}
function answer(skip){if(!quiz||quiz.answered)return;const q=quiz.questions[quiz.index],s=structures.find(s=>s.id===quiz.selection);quiz.answered=true;quiz.skipped=skip;quiz.wasCorrect=!skip&&lesson(s)?.id===q.id;if(quiz.wasCorrect){quiz.correct++;quiz.combo++;stats.correct++;stats.bestCombo=Math.max(stats.bestCombo,quiz.combo);const xp=quiz.hint?10:20;quiz.xp+=xp;award(xp);}else quiz.combo=0;const target=structures.find(s=>s.id===quiz.selection&&lesson(s)?.id===q.id)||structures.find(s=>lesson(s)?.id===q.id&&s.side==='left')||structures.find(s=>lesson(s)?.id===q.id);if(target){quiz.correctId=target.id;$('#layers').value='all';viewer.setLayer('all');viewer.reveal(target.id);$('#region').value=target.region;}updateRestore();renderQuiz();}
function nextQuestion(){if(++quiz.index>=quiz.questions.length){quiz.finished=true;stats.sessions.push({date:new Date().toISOString(),score:quiz.correct,total:quiz.questions.length,xp:quiz.xp,mode:quiz.type,complete:true});save();$('#layers').disabled=false;}else{quiz.selection=null;quiz.answered=false;quiz.hint=false;quiz.skipped=false;viewer.select(null);viewer.reset();viewer.frame(quizRegion==='essentials'?'all':quizRegion);$('#region').value=quizRegion==='essentials'?'all':quizRegion;$('#orientation').value='front';updateRestore();}renderQuiz();}
function progress(){document.body.classList.remove('quiz-on');$('#workspace').hidden=true;$('#progress-page').hidden=false;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.remove('active'));$('#progress-page').innerHTML=`<div class="eyebrow">Votre apprentissage</div><h1>Un muscle après l’autre.</h1><p>Niveau ${1+Math.floor(stats.xp/150)} · ${150-stats.xp%150} XP avant le prochain niveau</p><div class="progress-overview"><div><strong>${stats.xp}</strong><small>XP gagnés</small></div><div><strong>${stats.explored.length}</strong><small>Structures explorées</small></div><div><strong>${stats.bestCombo}</strong><small>Meilleure série de réponses</small></div></div><div class="badge-list">${[['◎','Explorateur',stats.explored.length>=10,'Explorer 10 structures'],['✓','Anatomiste',stats.correct>=20,'Réussir 20 questions'],['✦','Sans faute',stats.bestCombo>=5,'Enchaîner 5 bonnes réponses']].map(([icon,n,ok,d])=>`<div class="badge ${ok?'unlocked':''}"><span>${icon}</span><strong>${n}${ok?' · Obtenu':''}</strong><p>${d}</p></div>`).join('')}</div><h2>Dernières séries</h2>${stats.sessions.length?stats.sessions.slice(-8).reverse().map(s=>`<div class="history-row"><span>${new Date(s.date).toLocaleDateString('fr-FR')}</span><span>${s.mode==='name'?'Nom → corps':s.mode==='function'?'Fonction → muscle':'Défi'} · ${s.score} / ${s.total}</span><span>+${s.xp} XP</span></div>`).join(''):'<p>Votre premier défi vous attend.</p>'}<button class="primary wide" id="resume">Revenir à l’atlas</button><p style="font-size:11px">Progression conservée dans ce navigateur.</p>`;$('#resume').onclick=()=>setMode('explore');}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{ $('#detail').classList.remove('quiz-panel');setMode(b.dataset.mode);});$('#progress-open').onclick=progress;$('#search').oninput=search;$('#search').onkeydown=e=>{if(e.key==='Escape')$('#search-results').hidden=true;if(e.key==='ArrowDown'){e.preventDefault();$('#search-results button')?.focus();}};document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#search-results').hidden=true;});$('#region').onchange=e=>{viewer?.restore();viewer?.frame(e.target.value);$('#orientation').value='front';updateRestore();};$('#layers').onchange=e=>{viewer?.setLayer(e.target.value);updateRestore();};$('#orientation').onchange=e=>viewer?.orient(e.target.value);$('#zoom-in').onclick=()=>viewer?.zoom(.8);$('#zoom-out').onclick=()=>viewer?.zoom(1.25);$('#reset-view').onclick=()=>{viewer?.reset();$('#region').value='all';$('#layers').value='all';$('#orientation').value='front';updateRestore();};$('#restore').onclick=()=>{viewer.restore();$('#region').value='all';updateRestore();if(mode==='explore')renderDetail();};for(const m of ['rotate','pan'])$('#'+m+'-mode').onclick=()=>{viewer?.setMode(m);for(const t of ['rotate','pan']){$('#'+t+'-mode').classList.toggle('active',m===t);$('#'+t+'-mode').setAttribute('aria-pressed',String(m===t));}$('#navigation-hint').textContent=m==='pan'?'Glisser pour déplacer · Molette pour zoomer · Double-clic pour cibler':'Glisser pour tourner · Molette pour zoomer · Double-clic pour cibler';};$('#sources-open').onclick=()=>$('#sources-dialog').showModal();$('#sources-close').onclick=()=>$('#sources-dialog').close();
$('#source-content').innerHTML=`<h3>Une source 3D identifiable</h3><p>Modèle issu de <a href="https://github.com/Z-Anatomy/Models-of-human-anatomy" target="_blank" rel="noopener">Z-Anatomy</a>, dérivé de BodyParts3D. Les structures sont individualisées pour permettre une sélection précise.</p><h3>Pour préparer un examen de coach</h3><p>Les fiches expliquent les mouvements et proposent des exemples en salle. Elles ne correspondent pas à un référentiel de certification particulier. Un exercice fait intervenir plusieurs muscles : les exemples ne signifient pas qu’il isole le muscle présenté.</p><p>Pour approfondir les exercices : <a href="https://www.acefitness.org/resources/everyone/exercise-library/" target="_blank" rel="noopener">bibliothèque ACE</a>. Les notions de travail concentrique, excentrique et isométrique servent à analyser le rôle du muscle selon la phase du mouvement.</p><h3>Contenu pédagogique</h3><p>Les fiches sont des synthèses fondées sur <a href="https://openstax.org/details/books/anatomy-and-physiology-2e" target="_blank" rel="noopener">OpenStax Anatomy & Physiology</a> et les références indiquées dans chaque fiche. Les chefs d’un même muscle partagent une fiche qui précise leurs différences.</p><h3>Précision et limites</h3><p>Cet atlas représente une anatomie masculine de référence, pas toutes les variations individuelles. Les surfaces 3D n’indiquent pas à elles seules les empreintes exactes d’insertion. Les maillages de base sont conservés sans décimation ; les modificateurs Blender ne sont pas évalués. Les cavités fines de l’ethmoïde restent notamment à compléter. Une revue des correspondances et du contenu a été réalisée, mais l’application n’a pas encore été validée par un anatomiste ou un comité médical.</p><p>Les structures sans fiche documentée sont exclues des défis. Les catégories de profondeur servent à l’exploration ; elles ne simulent pas une dissection par plans régionaux.</p><h3>Crédits</h3><p>Z-Anatomy : Gauthier Kervyn et contributeurs. BodyParts3D : Database Center for Life Science. Modèles adaptés sous CC BY-SA, détails dans <a href="assets/Z-Anatomy-LICENSE.txt" target="_blank">la licence source</a>. Three.js : licence MIT.</p>`;
updateStats();welcome();
async function init(){try{const res=await fetch('assets/atlas.json');if(!res.ok)throw Error('Catalogue anatomique indisponible.');atlas=await res.json();structures=atlas.structures;viewer=new AnatomyViewer($('#viewer'),{onPick:pick,onHover:(s,e)=>{const t=$('#hover-label');t.hidden=!s||mode==='quiz';if(t.hidden)return;t.textContent=`${label(s)} · ${side(s.side)}`;const r=$('#viewer').getBoundingClientRect();t.style.left=Math.max(10,Math.min(e.clientX-r.left+15,r.width-270))+'px';t.style.top=Math.max(140,Math.min(e.clientY-r.top+15,r.height-100))+'px';},onView:t=>{$('#view-label').textContent=t;$('#hover-label').hidden=true;const v={'Vue antérieure':'front','Vue postérieure':'back','Profil gauche':'left','Profil droit':'right','Vue plantaire':'bottom','Vue ciblée':'custom'}[t];$('#orientation').value=v||'front';},onReady:error=>{if(error){$('#loading').hidden=false;$('#load-message').textContent=error.message;}}});await viewer.load(atlas,p=>$('#load-progress').value=Math.round(p*100));ready=true;$('#loading').hidden=true;$('#atlas-summary').textContent=`${structures.filter(s=>s.category==='muscle').length} structures musculaires · ${structures.filter(s=>s.category==='bone').length} structures osseuses`;if(mode==='quiz')renderQuiz();else if(!selected)welcome();}catch(e){$('#load-message').textContent=`Le modèle n’a pas pu être chargé : ${e.message}`;$('#load-progress').hidden=true;const b=document.createElement('button');b.textContent='Réessayer';b.onclick=()=>location.reload();$('#loading').append(b);}}
init();
